/bin/bash -lc "python3 - <<'PY'
from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self): super().__init__(); self.out=[]; self.skip=0
    def handle_starttag(self,t,a):
        if t in {'script','style','svg'}: self.skip+=1
    def handle_endtag(self,t):
        if t in {'script','style','svg'} and self.skip: self.skip-=1
    def handle_data(self,d):
        if not self.skip and d.strip(): self.out.append(d.strip())
p=P(); p.feed(open('/workspace/borzoi-paper.html').read());
text=' '.join(p.out)
for term in ['parameter','million','Borzoi consists','head']:
 print('\\nTERM',term)
 pos=0
 while True:
  i=text.lower().find(term.lower(),pos)
  if i<0: break
  print(text[max(0,i-350):i+500]); pos=i+1
PY"

